<template><form class="auo" @submit.prevent="submit"><header><span class="auo-kicker">选择后继续</span><h4>{{ node.title }}</h4><p v-if="node.intro">{{ node.intro }}</p></header><fieldset><legend class="aui-sr">{{ node.title }}{{ node.multiple?'（可多选）':'（单选）' }}</legend><label v-for="(option,i) in node.options" :key="option.value" :class="{'is-selected':selected.has(i)}"><input :type="node.multiple?'checkbox':'radio'" :name="scope+'-'+node.id" :checked="selected.has(i)" :disabled="disabled" @change="choose(i)"/><span><strong>{{ option.label }}</strong><small v-if="option.desc">{{ option.desc }}</small></span><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></label></fieldset><footer><span>{{ node.multiple?'可选择多个方向':'选择一项具体事项' }}</span><button type="submit" class="aui-action" :disabled="disabled||!selected.size">{{ node.submitLabel||'确认并继续' }} <span aria-hidden="true">→</span></button></footer></form></template>
<script setup lang="ts">
import {ref,watch} from 'vue'
import type {UiOptions} from '@/utils/agent-ui'
const props=defineProps<{node:UiOptions;disabled?:boolean;scope:string}>(),emit=defineEmits<{(e:'ask',message:string):void}>(),selected=ref(new Set<number>())
watch(()=>JSON.stringify(props.node.options),()=>selected.value=new Set())
function choose(i:number){if(props.disabled)return;const next=props.node.multiple?new Set(selected.value):new Set<number>();next.has(i)?next.delete(i):next.add(i);selected.value=next}
function submit(){if(props.disabled||!selected.value.size)return;emit('ask',[...selected.value].sort((a,b)=>a-b).map(i=>props.node.options[i].value).join('\n'))}
</script>
<style scoped>
.aui-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.auo{border:1px solid var(--aui-line);border-radius:18px;background:var(--aui-bg);padding:22px}.auo-kicker{font-size:10px;letter-spacing:.1em;color:var(--aui-accent)}h4{font-size:17px;line-height:1.6}header p{font-size:13px;color:var(--aui-muted);line-height:1.8;margin-top:8px!important;white-space:pre-wrap}fieldset{border:0;padding:0;margin:18px 0;display:grid;gap:10px}label{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid var(--aui-line);border-radius:12px;cursor:pointer;background:var(--aui-bg)}label.is-selected{border-color:var(--aui-accent);background:var(--aui-accent-soft)}input{accent-color:var(--aui-accent);width:17px;height:17px;flex-shrink:0}label>span{flex:1;min-width:0}strong{font-weight:550;font-size:14px}small{display:block;margin-top:4px;color:var(--aui-muted);font-size:12px;white-space:pre-wrap;line-height:1.8}svg{width:18px;height:18px;color:var(--aui-accent);flex-shrink:0}footer{display:flex;gap:14px;justify-content:space-between;align-items:center}footer>span{font-size:11px;color:var(--aui-muted)}.aui-action{display:flex;align-items:center;gap:14px;border:1px solid var(--nx-accent-border,var(--aui-line));border-radius:10px;padding:9px 12px;background:var(--aui-accent-soft);color:var(--aui-accent);font-size:12px}label:has(input:disabled){cursor:default}label:focus-within{outline:3px solid var(--nx-focus-ring);outline-offset:3px}@media(max-width:600px){.auo{padding:17px}label{padding:12px}}
</style>
